import{z as s,x as i,o as e,c as p,q as l,j as n,D as E,d as B,s as A,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"弱到强泛化","description":"","frontmatter":{"title":"弱到强泛化","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/weak-to-strong.md","filePath":"llm/weak-to-strong.md","lastUpdated":1791063341000}'),d={name:"llm/weak-to-strong.md"};function m(h,a,C,D,u,c){const r=i("Mermaid");return e(),p("div",null,[a[2]||(a[2]=l('<h1 id="弱到强泛化" tabindex="-1">弱到强泛化 <a class="header-anchor" href="#弱到强泛化" aria-label="Permalink to &quot;弱到强泛化&quot;">​</a></h1><div class="epigraph"><p>用弱模型的标签训练强模型，强模型有时能超过弱监督者——前提是弱标签仍与真值相关，而不是系统性地错。</p><footer>—— Burns 等，Weak-to-Strong Generalization，OpenAI</footer></div><p><a href="/llm/debate-oversight">上一课</a>希望弱裁判监督强辩手。更简单的设定是：弱监督者直接打标签，强学生做监督训练。缺口是：<strong>学生会不会只模仿弱者的错误天花板？</strong> Burns 等人用 GPT-4 当强、弱模型当监督者，在 NLP 与棋等任务上测量弱到强泛化。本课写这一现象与对齐含义，接到 <a href="/llm/rlhf-pipeline">RLHF</a> 里「人已经比模型弱」的未来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经典监督假设标签接近金标。对齐的远期问题是：人类（弱）给超人类模型（强）反馈。实验室代理：弱 LLM 的预测当标签，强 LLM 做 SFT 或线性探针，看强模型在金标上能否超过弱模型准确率。若能，说明强模型的预训练表征里已有更好概念，弱标签只是噪声索引。若不能，对齐会锁死在弱者水平。</p><p>Burns 等发现部分任务有明显的弱到强差距被部分恢复，也发现简单的「强模型拟合弱错误」失败模式。这不是已经解决可扩展监督，而是一个可测量的中间现象。恢复幅度随任务变：常识分类更乐观，需要精确监督的安全轴更悲观——后者正是对齐真正在乎的。</p><p><span class="marginnote">数字实例（示意）：弱模型标签准确率 70%，用这些标签训出的强学生在金标测试上到 75%——超过了老师，说明有泛化；但用金标直接训的强模型能到 90%，剩下的 15 个百分点就是「弱监督差距」。读论文时盯住三条线的相对位置：弱者、弱训学生、金标上限，单看「学生超过弱者」会高估进展。</span></p><h3 id="与蒸馏相反" tabindex="-1">与蒸馏相反 <a class="header-anchor" href="#与蒸馏相反" aria-label="Permalink to &quot;与蒸馏相反&quot;">​</a></h3><p>蒸馏用强教师标签训弱学生，天花板是教师。弱到强用弱教师训强学生，希望天花板是学生的预训练知识。方向相反，数据协议相似，解释完全不同。不要把 R1 蒸馏小模型叫做弱到强。</p><p><span class="marginnote">弱标签若有系统性偏见（总爱长、总拒答），强模型会把偏见学成原则，泛化的是偏见。相关噪声才可能被表征纠正。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>协议：弱模型在训练集上出软/硬标签 → 强模型拟合 → 在金标测试集上比较弱、强、以及强用金标训的上限。辅助：置信加权、表征探针、自洽。对齐迁移：人的比较当作弱标签，强策略做 <a href="/llm/dpo">DPO</a> / PPO，金标是更贵的专家抽检或下游任务。</p><p><span class="marginnote">术语翻译：软标签是概率分布（「这道题 0.8 像 A、0.2 像 B」），硬标签是单一答案（「选 A」）。弱到强实验里软标签更常用，因为它把弱模型的犹豫也传给了学生——学生能看出「老师自己也不确定」，而不是把一个错的答案当成确定真理去背。</span></p>',13)),(e(),n(o,null,{default:E(()=>[A(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%BC%B1%E7%9B%91%E7%9D%A3%E8%80%85%E6%A0%87%E7%AD%BE%22%5D%20--%3E%20FIT%5B%22%E5%BC%BA%E6%A8%A1%E5%9E%8B%E6%8B%9F%E5%90%88%22%5D%0A%20%20PRE%5B%22%E5%BC%BA%E6%A8%A1%E5%9E%8B%E9%A2%84%E8%AE%AD%E7%BB%83%E8%A1%A8%E5%BE%81%22%5D%20--%3E%20FIT%0A%20%20FIT%20--%3E%20GEN%5B%22%E9%87%91%E6%A0%87%E4%B8%8A%E6%98%AF%E5%90%A6%E8%B6%85%E8%BF%87%E5%BC%B1%E8%80%85%22%5D%0A%20%20GEN%20--%3E%20YES%5B%22%E5%BC%B1%E5%88%B0%E5%BC%BA%E6%B3%9B%E5%8C%96%22%5D%0A%20%20GEN%20--%3E%20NO%5B%22%E9%94%81%E5%9C%A8%E5%BC%B1%E5%A4%A9%E8%8A%B1%E6%9D%BF%20%2F%20%E6%8B%9F%E5%90%88%E5%81%8F%E8%A7%81%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[B("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"一种解释：弱标签与真值在简单特征上相关，强模型还能用复杂特征去噪。辩论、过程监督试图提高「弱标签与真值的相关」，使泛化更容易。若弱者在关键安全轴上系统性错，去噪会朝错误方向。因此弱到强不能替代红队；它只说明能力轴上可能有恢复。",-1)),(e(),n(o,null,{default:E(()=>[A(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20WL%5B%22%E5%BC%B1%E6%A0%87%E7%AD%BE%22%5D%20--%3E%20Q%7B%22%E5%BC%B1%E6%A0%87%E7%AD%BE%E4%B8%8E%E7%9C%9F%E5%80%BC%E6%98%AF%E4%BB%80%E4%B9%88%E5%85%B3%E7%B3%BB%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E8%BF%91%E4%BC%BC%E9%9A%8F%E6%9C%BA%E5%99%AA%E5%A3%B0%22%7C%20D%5B%22%E5%BC%BA%E6%A8%A1%E5%9E%8B%E7%94%A8%E9%A2%84%E8%AE%AD%E7%BB%83%E8%A1%A8%E5%BE%81%E5%8E%BB%E5%99%AA%22%5D%0A%20%20D%20--%3E%20R%5B%22%E6%B3%9B%E5%8C%96%EF%BC%9A%E9%87%91%E6%A0%87%E4%B8%8A%E8%B6%85%E8%BF%87%E5%BC%B1%E8%80%85%22%5D%0A%20%20Q%20--%3E%7C%22%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%81%8F%E8%A7%81%22%7C%20B%5B%22%E6%8A%8A%E5%81%8F%E8%A7%81%E5%AD%A6%E6%88%90%E8%AE%AD%E7%BB%83%E7%9B%AE%E6%A0%87%22%5D%0A%20%20B%20--%3E%20W%5B%22%E8%B6%8A%E8%AE%AD%E8%B6%8A%E9%94%99%EF%BC%9A%E6%B3%9B%E5%8C%96%E7%9A%84%E6%98%AF%E5%81%8F%E8%A7%81%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">数字实例（PCT 指标）：弱者 70%、弱训学生 75%、金标上限 90% 时，弱到强差距是 90 − 70 = 20 个百分点，被恢复的是 75 − 70 = 5 个，恢复比例 PCT = 5 ÷ 20 = 25%。论文用它跨任务比较「恢复了多少」，比只报「学生超过了弱者」诚实得多。</span></p><p><span class="marginnote">实验用的弱/强是同族不同规模，不是人类 vs 未来模型。外推要谨慎。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>有校验器则用校验器，不必弱标签。开放对齐才需要。下一课把弱到强、辩论、递归奖励模型收成可扩展监督纲领，并写它们共同的失败：监督信号被优化后失效。</p><p>弱标签的系统性偏见会被强模型学成原则。本课只保证：在弱–金标仍相关的任务上，表征有时能去噪。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>弱到强：用弱标签训强模型，看金标上能否超过弱者。</li><li>与蒸馏方向相反；R1 学生蒸馏不是本课。</li><li>系统性偏见会被放大；只有近似噪声才可能被表征纠正。</li><li>是可测量现象，不是已完成的对齐方案。</li><li>出处：Burns 等 Weak-to-Strong Generalization；对照 Irving 辩论、Christiano 偏好 RL。</li></ul>',7))])}const _=s(d,[["render",m]]);export{F as __pageData,_ as default};
